from scipy.optimize import least_squares
def model(p,fam):
    a,b,k,d,w,m=p
    base=a*A**3+b*np.exp(-k*t**2)
    if fam=='sin': g=np.sin(w*t)
    elif fam=='cos': g=np.cos(w*t)
    elif fam=='exp': g=np.exp(-w*t)
    elif fam=='lin': g=t
    elif fam=='texp': g=t*np.exp(-w*t)
    return base+d*g*A**m
